149: function normalizeHex(value, { allowShort = true } = {}) {
150:   if (typeof value !== 'string') return null;
151:   let hex = value.trim().replace(/^#/, '');
152:   if (!/^[0-9a-f]+$/i.test(hex)) return null;
153:   if (allowShort && hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
154:   if (hex.length !== 6) return null;
155:   return `#${hex.toUpperCase()}`;
156: }
157: 
158: function hexToInt(hex) { return parseInt(hex.slice(1), 16); }
