2403: // The racing line: cut the apex, run wide on exit, and gradually settle back to
2404: // the middle on straights. Every driver leans on the kerbs a little differently.
2405: function aiRacingLine(a, s, limit) {
2406:   const tight = clamp(Math.abs(s.k) / (1 / 58), 0, 1);
2407:   const apex = Math.sign(s.k) * limit * (0.62 + a.nerve * 0.22) * tight;
2408:   const weave = Math.sin(a.dist / 74 + a.phase) * 0.28 * (1 - tight);
2409:   if (a.finished) return -Math.sign(s.k || 1) * limit * 0.55;
2410:   return apex + weave;
