2494: function aiPitAhead(a) {
2495:   const pit = a.pit;
2496:   if (pit.phase !== 'in' && pit.phase !== 'out') return null;
2497:   let ahead = null;
2498:   let gap = Infinity;
2499:   for (const b of race.ai) {
2500:     if (b === a) continue;
2501:     const other = b.pit;
2502:     // Service cars are pulled left against their garage, so the through-lane
2503:     // stays open. Everything moving up the lane is traffic for everyone else.
2504:     if (other.phase !== 'in' && other.phase !== 'out') continue;
2505:     const d = other.routeProgress - pit.routeProgress;
2506:     if (d > 0 && d < gap) {
2507:       gap = d;
2508:       ahead = b;
2509:     }
2510:   }
2511:   return ahead ? { car: ahead, gap } : null;
2512: }
