import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({
  headless: false,
  executablePath: '/opt/google/chrome/chrome',
  args: ['--no-sandbox']
});

async function check(aiCount, trackIndex) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.addInitScript((n) => localStorage.setItem('apexink.ai', String(n)), aiCount);
  await page.goto(`http://localhost:3000/?demo=race&track=${trackIndex}`, { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
  await page.waitForTimeout(400);

  const result = await page.evaluate(() => {
    const r = window.__apex.race;
    const cars = [
      { name: 'YOU', pose: r.player.gridPose, x: r.player.pos.x, z: r.player.pos.z },
      ...r.ai.map((a) => ({ name: a.name, pose: a.gridPose, x: a.model.root.position.x, z: a.model.root.position.z }))
    ];
    const seatErr = cars.map((c) => ({
      name: c.name,
      slot: c.pose?.slot,
      err: c.pose ? Math.hypot(c.x - c.pose.x, c.z - c.pose.z) : null
    }));
    const meshCount = r.startGrid.children.length;
    // Each slot paints 5 bars (2 rails, 2 ends, 1 accent), in slot order.
    const boxChecks = [];
    for (let slot = 0; slot < r.ai.length + 1; slot++) {
      const pose = slot === r.ai.length ? r.player.gridPose : r.ai.find((a) => a.gridPose.slot === slot)?.gridPose;
      if (!pose) continue;
      const from = slot * 5;
      const bars = r.startGrid.children.slice(from, from + 5).map((m) => ({ x: m.position.x, z: m.position.z }));
      const expected = [
        [-1.75, 0], [1.75, 0], [0, 3.1], [0, -3.1], [0, 0]
      ];
      const fx = Math.sin(pose.yaw), fz = Math.cos(pose.yaw);
      const nx = fz, nz = -fx;
      let maxErr = 0;
      for (let i = 0; i < 4; i++) {
        const ex = pose.x + nx * expected[i][0] + fx * expected[i][1];
        const ez = pose.z + nz * expected[i][0] + fz * expected[i][1];
        maxErr = Math.max(maxErr, Math.hypot(bars[i].x - ex, bars[i].z - ez));
      }
      boxChecks.push({ slot, maxErr: +maxErr.toFixed(4) });
    }
    // grid should be on the track surface, not floating or buried
    const boxY = [...new Set(r.startGrid.children.map((m) => +m.position.y.toFixed(3)))];

    // Lights out must not move the displayed cars.
    const before = {
      player: { x: r.player.pos.x, z: r.player.pos.z, yaw: r.player.yaw, pd: r.player.progressDist },
      ai: r.ai.map((a) => ({ name: a.name, d: a.dist, lat: a.lateral, x: a.lastX, z: a.lastZ }))
    };
    window.__apex.startRaceNow();
    const snap = (t) => ({
      player: { x: r.player.pos.x, z: r.player.pos.z, pd: r.player.progressDist, v: r.player.vLong, lat: r.player.lateral ?? 0 },
      ai: r.ai.map((a) => ({ name: a.name, d: a.dist, lat: a.lateral, sp: a.speed, x: a.lastX, z: a.lastZ }))
    });
    const afterAnchor = snap(0);
    const maxLateral = r.ai.map(() => 0);
    const minDist = r.ai.map(() => Infinity);
    const maxDist = r.ai.map(() => -Infinity);
    const samples = [];
    for (let i = 0; i < 240; i++) {
      window.__apex.tick(1 / 60);
      r.ai.forEach((a, idx) => {
        maxLateral[idx] = Math.max(maxLateral[idx], Math.abs(a.lateral - a.gridLateral));
        minDist[idx] = Math.min(minDist[idx], a.dist);
        maxDist[idx] = Math.max(maxDist[idx], a.dist);
