    track: run.trackIndex,
    errors: run.errors,
    meshes: r.meshCount,
    expectedMeshes: (run.aiCount + 1) * 5,
    seatMax: +seatMax.toFixed(4),
    boxMax: +boxMax.toFixed(4),
    boxY: r.boxY,
    anchorPlayer: +anchorPlayer.toFixed(4),
    anchorAi: +anchorAi.toFixed(4),
    lateralMax,
    state: r.state,
    final: late,
    distRange: r.distRange
  }, null, 1));
  if (run.errors.length || r.meshCount !== (run.aiCount + 1) * 5 || seatMax > 0.01 || boxMax > 0.01 || anchorPlayer > 0.01 || anchorAi > 0.01 || !allMoving) failures++;
}
