import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({
  headless: false,
  executablePath: '/opt/google/chrome/chrome',
  args: ['--no-sandbox']
});
const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(() => localStorage.setItem('apexink.ai', '3'));
await page.goto('http://localhost:3000/?demo=race&track=0', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
await page.waitForTimeout(500);

const prep = await page.evaluate(() => {
  const r = window.__apex.race;
  window.__apex.startRaceNow();
  const box = r.world.playerPitBox;
  const { boxDistance } = { boxDistance: r.world.pitBoxDistance };
  r.pit.phase = 'driving-in';
  r.pit.entryProgress = 0;
  r.pit.routeProgress = boxDistance - 40;
  r.player.progressDist = r.pit.routeProgress;
  r.player.pos.x = box.x;
  r.player.pos.z = box.z;
  r.player.yaw = box.yaw;
  r.player.vel.x = 0;
  r.player.vel.z = 0;
  r.player.vLong = 0;
  for (let i = 0; i < 75; i++) window.__apex.tick(1 / 60);
  const crew = box.crew.map((c) => ({
    wheel: c.wheel,
    x: +c.x.toFixed(3), z: +c.z.toFixed(3),
    tx: c.target.x, tz: c.target.z,
    err: +Math.hypot(c.x - c.target.x, c.z - c.target.z).toFixed(3)
  }));
  return { box: { x: box.x, z: box.z, yaw: box.yaw }, boxDistance, phase: r.pit.phase, crew, route: r.pit.routeProgress, car: { x: r.player.pos.x, z: r.player.pos.z } };
});
console.log('DEPLOY', JSON.stringify(prep, null, 1));

// Freeze and frame the box for a clean look at crews on their corners.
await page.evaluate(() => {
  const r = window.__apex.race;
  const b = r.world.playerPitBox;
  r.state = 'paused';
  r.camera.position.set(b.x - Math.cos(b.yaw) * 9 + Math.sin(b.yaw) * 2, 10.5, b.z + Math.sin(b.yaw) * 9 + Math.cos(b.yaw) * 2);
  r.camera.lookAt(b.x, 0.5, b.z);
});
await page.waitForTimeout(200);
await page.screenshot({ path: '/tmp/opencode/pit-crew-ready.jpg', type: 'jpeg', quality: 80 });

const service = await page.evaluate(() => {
  const r = window.__apex.race;
