import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome', args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(() => localStorage.setItem('apexink.ai', '3'));
await page.goto('http://localhost:3000/?demo=race&track=0', { waitUntil: 'domcontentloaded' });
await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
await page.waitForTimeout(400);

const result = await page.evaluate(() => {
  const r = window.__apex.race;
  const tick = (n) => { for (let i = 0; i < n; i++) window.__apex.tick(1 / 60); };
  window.__apex.startRaceNow();
  const b = r.world.playerPitBox;
  const dist = () => Math.hypot(b.x - r.player.pos.x, b.z - r.player.pos.z);
  const crewState = () => b.crew.map((c) => ({
    wheel: c.wheel,
    x: +c.x.toFixed(3), z: +c.z.toFixed(3),
    idleErr: +Math.hypot(c.x - c.idle.x, c.z - c.idle.z).toFixed(3),
    targetErr: +Math.hypot(c.x - c.target.x, c.z - c.target.z).toFixed(3),
    y: +c.group.position.y.toFixed(3),
    armX: +c.armA.rotation.x.toFixed(2)
  }));
  const wheelState = () => r.playerCar.wheels.map((w, i) => ({
    corner: ['fl', 'fr', 'rl', 'rr'][i],
    x: +w.steer.position.x.toFixed(3),
    y: +w.steer.position.y.toFixed(3),
    z: +w.steer.position.z.toFixed(3),
    rotZ: +w.steer.rotation.z.toFixed(3),
    blend: +(w.pitBlend ?? 0).toFixed(2)
  }));

  const idle = crewState();

  // Put the car in the last 14 m of its approach and let the integration run.
  r.pit.phase = 'driving-in';
  r.pit.entryProgress = 0;
  r.pit.entryDistance = 0;
  r.pit.routeProgress = r.world.pitBoxDistance - 13;
  r.player.progressDist = r.pit.routeProgress;
  r.player.pos.x = b.x;
  r.player.pos.z = b.z;
  r.player.yaw = b.yaw;
  r.player.vel.x = 0; r.player.vel.z = 0;
  r.player.vLong = 0; r.player.vLat = 0;
  tick(12);
  const midwalk = crewState();

  // Finish the approach, which opens the tyre service.
  r.pit.routeProgress = r.world.pitBoxDistance - 0.1;
  r.player.pos.x = b.x; r.player.pos.z = b.z;
  r.player.progressDist = r.world.pitBoxDistance;
  tick(2);
  const servicePhase = r.pit.phase;
  tick(50);
  const working = crewState();

  const click = (key) => document.querySelector(`.pit-mini-wheel-btn[data-wheel="${key}"]`)?.click();
  const removals = [];
  for (const key of ['fl', 'fr', 'rl', 'rr']) {
    click(key);
    tick(22);
    removals.push({ key, state: r.pit.wheels[key], stage: r.pit.serviceStage });
  }
  const removed = { stage: r.pit.serviceStage, wheels: { ...r.pit.wheels }, visuals: wheelState() };

  const fittings = [];
  for (const key of ['fl', 'fr', 'rl', 'rr']) {
    click(key);
    tick(22);
    fittings.push({ key, state: r.pit.wheels[key], stage: r.pit.serviceStage });
  }
  const fitted = { stage: r.pit.serviceStage, wheels: { ...r.pit.wheels }, visuals: wheelState() };

  tick(70);
  const afterStopPhase = r.pit.phase;
  tick(60);
  const retracted = { phase: r.pit.phase, crew: crewState(), visuals: wheelState(), distToBox: +dist().toFixed(1) };

  window.__apex.restartRace();
  const restarted = {
    state: r.state,
    crew: crewState(),
    visuals: wheelState(),
    boxes: r.startGrid.children.length
  };

  return { idle, midwalk, servicePhase, working, removals, removed, fittings, fitted, afterStopPhase, retracted, restarted };
});

console.log(JSON.stringify(result, null, 1));
console.log('ERRORS', JSON.stringify(errors));
await browser.close();

import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = process.env.HOME + '/.local/share/omgithub-playwright';
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: false, executablePath: '/opt/google/chrome/chrome', args: ['--no-sandbox'] });

async function run(aiCount, trackIndex) {
  const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.addInitScript((n) => localStorage.setItem('apexink.ai', String(n)), aiCount);
  await page.goto(`http://localhost:3000/?demo=race&track=${trackIndex}`, { waitUntil: 'domcontentloaded' });
  await page.waitForFunction(() => window.__apex?.race, null, { timeout: 30000 });
  await page.waitForTimeout(300);
  const result = await page.evaluate(() => {
    const r = window.__apex.race;
    window.__apex.startRaceNow();
    const b = r.world.playerPitBox;
    const tick = (n) => { for (let i = 0; i < n; i++) window.__apex.tick(1 / 60); };
    const idleOk = b.crew.every((c) => Math.hypot(c.x - c.idle.x, c.z - c.idle.z) < 0.01);
    r.pit.phase = 'driving-in';
    r.pit.entryProgress = 0;
    r.pit.routeProgress = r.world.pitBoxDistance - 0.1;
    r.pit.entryDistance = 0;
    r.player.pos.x = b.x; r.player.pos.z = b.z; r.player.yaw = b.yaw;
    r.player.vel.x = 0; r.player.vel.z = 0; r.player.vLong = 0;
    tick(3);
    const servicing = r.pit.phase === 'servicing';
    tick(40);
    document.querySelector('.pit-mini-wheel-btn[data-wheel="fl"]')?.click();
    tick(25);
    const off = r.playerCar.wheels[0];
    document.querySelector('.pit-mini-wheel-btn[data-wheel="fr"]')?.click();
    tick(25);
    const twoOff = r.playerCar.wheels.slice(0, 2).every((w) => w.pitBlend > 0.95);
    const crewWork = b.crew.every((c) => Math.hypot(c.x - c.target.x, c.z - c.target.z) < 0.01 && c.armA.rotation.x < -0.5);
    return {
      ai: r.ai.length,
      boxes: r.startGrid.children.length,
      crew: b.crew.length,
      idleOk,
      servicing,
      flOff: { blend: +off.pitBlend.toFixed(2), x: +off.steer.position.x.toFixed(2), z: +off.steer.position.z.toFixed(2) },
      twoOff,
      crewWork
    };
  });
  await context.close();
  return { aiCount, trackIndex, result, errors };
}

for (const [ai, track] of [[0, 0], [9, 2], [6, 1]]) {
  console.log(JSON.stringify(await run(ai, track)));
}
await browser.close();

