await page.waitForTimeout(300);
const result = await page.evaluate(() => {
  const r = window.__apex.race;
  window.__apex.startRaceNow();
  const b = r.world.playerPitBox;
  const route = r.world.pitRoute;
  const boxRoute = r.world.pitBoxDistance;
  const approach = boxRoute - 14;
  const i = Math.floor(approach / 5);
  const f = approach / 5 - i;
  const a = route[i], c = route[Math.min(i + 1, route.length - 1)];
  const x0 = a.x + (c.x - a.x) * f;
  const z0 = a.z + (c.z - a.z) * f;
  const tx = a.tx + (c.tx - a.tx) * f;
  const tz = a.tz + (c.tz - a.tz) * f;
  const nx = tz, nz = -tx;
  // Remaining 14 m is inside the merge zone, so the car is part-way left.
  const merge = 3.6 * (1 - (() => { const t = Math.min(1, Math.max(0, 14 / 36)); return t * t * (3 - 2 * t); })());
  r.pit.phase = 'driving-in';
  r.pit.entryProgress = 0;
  r.pit.entryDistance = 0;
  r.pit.routeProgress = approach;
  r.player.progressDist = approach;
  r.player.pos.x = x0 + nx * merge;
  r.player.pos.z = z0 + nz * merge;
  r.player.yaw = Math.atan2(tx, tz);
  r.player.vel.x = 0; r.player.vel.z = 0;
  r.player.vLong = 0; r.player.vLat = 0;
  let frames = 0;
  const crewSamples = [];
  while (r.pit.phase !== 'servicing' && frames < 600) {
    window.__apex.tick(1 / 60);
    frames++;
    if (frames === 1 || frames === 30 || frames === 60 || frames === 90) {
      crewSamples.push({ frames, err: +Math.max(...b.crew.map((c) => Math.hypot(c.x - c.target.x, c.z - c.target.z))).toFixed(2) });
    }
