394:   const geo = new THREE.PlaneGeometry(width, depth);
395:   geo.rotateX(-Math.PI / 2);
396:   const mesh = new THREE.Mesh(geo, material);
397:   mesh.position.set(sample.x, y, sample.z);
398:   mesh.rotation.y = Math.atan2(sample.tx, sample.tz) + angleOffset;
399:   mesh.receiveShadow = true;
400:   return mesh;
401: }
