407: function createSky(sunDir) {
408:   const vertex = `
409:     varying vec3 vDir;
410:     void main() {
411:       vDir = normalize(position);
412:       gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
413:     }`;
414:   const fragment = `
415:     varying vec3 vDir;
416:     uniform vec3 uSun;
417:     void main() {
418:       vec3 d = normalize(vDir);
419:       float h = clamp(d.y, -0.15, 1.0);
420:       vec3 horizon = vec3(0.83, 0.80, 0.72);
421:       vec3 mid = vec3(0.60, 0.70, 0.76);
422:       vec3 top = vec3(0.24, 0.43, 0.63);
423:       vec3 col = mix(horizon, mid, smoothstep(0.0, 0.22, h));
424:       col = mix(col, top, smoothstep(0.18, 0.72, h));
425:       float sun = max(dot(d, normalize(uSun)), 0.0);
426:       col += vec3(1.0, 0.62, 0.30) * pow(sun, 24.0) * 0.45;
427:       col += vec3(1.0, 0.78, 0.5) * pow(sun, 500.0) * 1.6;
428:       col = mix(col, vec3(0.95, 0.72, 0.52), pow(1.0 - max(h, 0.0), 8.0) * 0.22);
429:       gl_FragColor = vec4(col, 1.0);
430:     }`;
431:   const mat = new THREE.ShaderMaterial({
432:     vertexShader: vertex,
433:     fragmentShader: fragment,
434:     uniforms: { uSun: { value: sunDir.clone().normalize() } },
435:     side: THREE.BackSide,
436:     depthWrite: false,
437:     fog: false
438:   });
439:   const mesh = new THREE.Mesh(new THREE.SphereGeometry(4200, 32, 18), mat);
440:   mesh.frustumCulled = false;
441:   return mesh;
442: }
