444: function cloudTexture() {
445:   const c = makeTextCanvas(256, 128, (ctx, w, h) => {
446:     ctx.clearRect(0, 0, w, h);
447:     for (let i = 0; i < 18; i++) {
448:       const x = 40 + Math.random() * (w - 80);
449:       const y = 45 + Math.random() * (h - 70);
450:       const r = 18 + Math.random() * 34;
451:       const g = ctx.createRadialGradient(x, y, 0, x, y, r);
452:       g.addColorStop(0, 'rgba(255,255,255,.5)');
453:       g.addColorStop(1, 'rgba(255,255,255,0)');
454:       ctx.fillStyle = g;
455:       ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
456:     }
457:   });
458:   return canvasTexture(c);
459: }
