607: 
608:   /* ── start gantry ───────────────────────────────────────────── */
609:   const gantry = new THREE.Group();
610:   const metalMat = new THREE.MeshStandardMaterial({ color: 0x24272d, roughness: 0.45, metalness: 0.8 });
611:   const signMat = new THREE.MeshStandardMaterial({ color: 0x111318, roughness: 0.5, metalness: 0.4 });
