619:   const beam = new THREE.Mesh(new THREE.BoxGeometry(track.halfWidth * 2 + 6, 0.75, 0.9), metalMat);
620:   beam.position.set(0, 7.25, 0);
621:   beam.castShadow = true;
622:   gantry.add(beam);
623:   const banner = new THREE.Mesh(new THREE.BoxGeometry(track.halfWidth * 1.5, 1.5, 0.15), signMat);
624:   banner.position.set(0, 6.2, 0);
625:   gantry.add(banner);
626:   const bannerTex = canvasTexture(makeTextCanvas(512, 96, (ctx, w, h) => {
627:     ctx.fillStyle = '#111318'; ctx.fillRect(0, 0, w, h);
628:     ctx.fillStyle = '#f3efe5'; ctx.font = '700 52px Rajdhani'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
629:     ctx.fillText('APEX INK', w / 2, h / 2 + 2);
