637:   const startLights = [];
638:   for (let i = 0; i < 5; i++) {
639:     const mat = new THREE.MeshStandardMaterial({ color: 0x220606, emissive: 0xff1a0a, emissiveIntensity: 0.05, roughness: 0.3 });
640:     const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.17, 12, 8), mat);
