649:   /* ── scenery placement helpers ───────────────────────────────── */
650:   const roadPts = [];
651:   for (let i = 0; i < track.N; i += 4) roadPts.push(track.samples[i]);
652:   const distanceToRoad = (x, z) => {
653:     let best = Infinity;
654:     for (const p of roadPts) {
655:       const d = (p.x - x) ** 2 + (p.z - z) ** 2;
656:       if (d < best) best = d;
