666:       const rad = Math.sqrt(rng()) * worldExtent;
667:       const x = track.centerX + Math.cos(ang) * rad;
668:       const z = track.centerZ + Math.sin(ang) * rad;
669:       if (distanceToRoad(x, z) < minRoad) continue;
670:       if (nearStart(x, z)) continue;
671:       return { x, z };
672:     }
673:     return null;
674:   };
