687:   const greenPalette = [0x3f5f2e, 0x4b7034, 0x35552a, 0x557c3b, 0x2f4b28, 0x668c45, 0x486b30];
688:   const dummy = new THREE.Object3D();
689:   let treeIdx = 0;
690:   let guard = 0;
691:   while (treeIdx < treeCount && guard++ < 3000) {
692:     const p = spot(17);
693:     if (!p) continue;
