713:   // bushes
714:   const bushCount = 110;
715:   const bushGeo = new THREE.IcosahedronGeometry(1, 0);
716:   const bushMat = new THREE.MeshStandardMaterial({ color: 0x3d5b2d, roughness: 0.95, flatShading: true });
717:   const bushes = new THREE.InstancedMesh(bushGeo, bushMat, bushCount);
718:   let bushIdx = 0;
719:   guard = 0;
720:   while (bushIdx < bushCount && guard++ < 1200) {
721:     const p = spot(12);
722:     if (!p) continue;
723:     const s = 0.35 + rng() * 0.75;
724:     dummy.position.set(p.x, 0.35 * s, p.z);
725:     dummy.rotation.set(0, rng() * TAU, 0);
726:     dummy.scale.set(s * 1.4, s, s * 1.4);
727:     dummy.updateMatrix();
728:     bushes.setMatrixAt(bushIdx, dummy.matrix);
729:     bushes.setColorAt(bushIdx, new THREE.Color(greenPalette[(rng() * greenPalette.length) | 0]));
730:     bushIdx++;
731:   }
732:   bushes.count = bushIdx;
733:   bushes.castShadow = true;
734:   scene.add(bushes);
