736:   /* ── distant mountains ───────────────────────────────────────── */
737:   const mountainGroup = new THREE.Group();
738:   const mountainMat = new THREE.MeshStandardMaterial({ color: 0x6d8291, roughness: 1, flatShading: true });
739:   const mountainMat2 = new THREE.MeshStandardMaterial({ color: 0x8799a4, roughness: 1, flatShading: true });
740:   const mountainRadius = Math.max(850, Math.max(track.bbox.width, track.bbox.depth) + 520);
741:   for (let i = 0; i < 20; i++) {
742:     const ang = (i / 20) * TAU + rng() * 0.2;
743:     const dist = mountainRadius * (0.85 + rng() * 0.5);
744:     const h = 90 + rng() * 190;
745:     const w = 120 + rng() * 260;
746:     const m = new THREE.Mesh(new THREE.ConeGeometry(w, h, 5 + Math.floor(rng() * 3)), rng() > 0.5 ? mountainMat : mountainMat2);
747:     m.position.set(track.centerX + Math.cos(ang) * dist, h * 0.42, track.centerZ + Math.sin(ang) * dist);
748:     m.rotation.y = rng() * TAU;
749:     mountainGroup.add(m);
750:   }
751:   scene.add(mountainGroup);
752: 
753:   /* ── grandstands ─────────────────────────────────────────────── */
754:   const crowdTex = crowdTexture();
755:   disposables.push(crowdTex);
756:   const crowdMat = new THREE.MeshStandardMaterial({ map: crowdTex, roughness: 0.9 });
757:   const standConcrete = new THREE.MeshStandardMaterial({ color: 0x9b978c, roughness: 0.9 });
758:   const standDark = new THREE.MeshStandardMaterial({ color: 0x2a2e35, roughness: 0.7, metalness: 0.35 });
759:   const standRoof = new THREE.MeshStandardMaterial({ color: 0xd9d4c8, roughness: 0.65, metalness: 0.2 });
760: 
761:   function standClearance(s, side, offset, width) {
762:     let min = Infinity;
763:     const front = Math.max(12, offset - 8.5);
764:     for (let k = 0; k <= 4; k++) {
765:       const lx = -width / 2 + (width * k) / 4;
766:       const px = s.x + s.tx * lx + s.nx * side * front;
767:       const pz = s.z + s.tz * lx + s.nz * side * front;
768:       for (let i = 0; i < track.N; i += 2) {
769:         const q = track.samples[i];
770:         const d = Math.hypot(q.x - px, q.z - pz);
771:         if (d < min) min = d;
772:       }
773:     }
774:     return min;
775:   }
776: 
777:   function makeGrandstand(index, width = 40) {
778:     const s = track.samples[(index + track.N) % track.N];
779:     let side = 1;
780:     let offset = track.halfWidth + 30;
781:     let clearance = -Infinity;
782:     for (const candidate of [-1, 1]) {
783:       let dist = track.halfWidth + 30;
784:       let clr = standClearance(s, candidate, dist, width);
785:       for (let attempt = 0; attempt < 3 && clr < 24; attempt++) {
786:         dist += 24 - clr + 2;
787:         clr = standClearance(s, candidate, dist, width);
788:       }
789:       if (clr > clearance) {
790:         clearance = clr;
791:         side = candidate;
792:         offset = dist;
793:       }
794:     }
795:     const g = new THREE.Group();
796:     const base = new THREE.Mesh(new THREE.BoxGeometry(width, 1.2, 17), standConcrete);
797:     base.position.y = 0.6;
798:     base.receiveShadow = true; base.castShadow = true;
799:     g.add(base);
800:     const seating = new THREE.Mesh(new THREE.BoxGeometry(width - 2, 7.4, 13), standDark);
801:     seating.position.set(0, 4.6, 0.6);
802:     seating.rotation.x = -0.12;
803:     seating.castShadow = true;
804:     g.add(seating);
805:     const crowd = new THREE.Mesh(new THREE.PlaneGeometry(width - 3, 6.8), crowdMat);
806:     crowd.position.set(0, 4.4, -5.4);
807:     crowd.rotation.x = 0.1;
808:     g.add(crowd);
809:     const roof = new THREE.Mesh(new THREE.BoxGeometry(width + 3, 0.45, 18), standRoof);
810:     roof.position.set(0, 10.1, -1);
811:     roof.rotation.x = 0.06;
812:     roof.castShadow = true;
813:     g.add(roof);
814:     for (const x of [-width / 2 + 2, 0, width / 2 - 2]) {
815:       const col = new THREE.Mesh(new THREE.BoxGeometry(0.35, 9.6, 0.35), standDark);
816:       col.position.set(x, 5.1, -8.4);
817:       g.add(col);
818:     }
819:     const trim = new THREE.Mesh(new THREE.BoxGeometry(width, 0.25, 0.3), new THREE.MeshStandardMaterial({ color: 0xff4d1f, emissive: 0x3a0c02, emissiveIntensity: 0.4 }));
820:     trim.position.set(0, 10.35, -9.8);
821:     g.add(trim);
822:     g.position.set(s.x + s.nx * side * offset, 0, s.z + s.nz * side * offset);
823:     g.rotation.y = Math.atan2(s.tx, s.tz) + (side > 0 ? -Math.PI / 2 : Math.PI / 2);
824:     scene.add(g);
825:     return g;
826:   }
827:   makeGrandstand(track.N - Math.round(34 / track.step), 42);
828:   makeGrandstand(track.N - Math.round(95 / track.step), 34);
829: 
830:   /* ── pit lane, boxes and ten detailed team garages ───────────── */
831:   const pitSide = 1;
832:   const pitOffset = track.halfWidth + 8.2;
833:   const pitEntryLead = 190;
834:   const pitSpan = 380;
835:   const PIT_ROAD_HALF = 5.4;
836:   const PIT_BOX_LATERAL = 3.6;
837:   const GARAGE_LATERAL = 12.5;
838:   const pitEntryDistance = track.length - pitEntryLead;
839:   const pitSampleAt = (distance) => {
840:     const wrapped = ((distance % track.length) + track.length) % track.length;
841:     const i = Math.floor(wrapped / track.step) % track.N;
842:     const next = track.samples[(i + 1) % track.N];
