302: function updatePitWheelVisuals(dt) {
303:   const car = race?.playerCar;
304:   if (!car) return;
305:   const wheels = race.pit?.wheels || freshPitWheels();
306:   for (const key of PIT_WHEELS) {
307:     const w = car.wheels[PIT_WHEEL_INDEX[key]];
308:     if (!w) continue;
309:     ensurePitWheelBase(w);
310:     const target = wheels[key] === 'removed' ? 1 : 0;
311:     w.pitBlend = damp(w.pitBlend, target, 10, dt);
312:     if (Math.abs(w.pitBlend - target) < 0.005) w.pitBlend = target;
313:     const t = smoothstep(0, 1, w.pitBlend);
314:     w.steer.position.x = lerp(w.pitBase.x, w.pitRest.x, t);
315:     w.steer.position.y = lerp(w.pitBase.y, w.pitRest.y, t);
316:     w.steer.position.z = lerp(w.pitBase.z, w.pitRest.z, t);
317:     w.steer.rotation.z = w.pitOut * (Math.PI / 2) * t;
318:     if (t > 0.001 && t < 0.999) {
319:       w.spin.rotation.x += dt * (3.2 + t * 8) * w.pitOut;
