274: function ensurePitWheelBase(w) {
275:   if (w.pitBase) return;
276:   w.pitBase = {
277:     x: w.steer.position.x,
278:     y: w.steer.position.y,
279:     z: w.steer.position.z
280:   };
281:   w.pitOut = Math.sign(w.steer.position.x) || 1;
282:   w.pitRest = {
283:     x: w.pitBase.x + w.pitOut * PIT_WHEEL_REST_OUT,
284:     y: w.width * 0.5 + 0.015,
285:     z: w.pitBase.z + (w.z > 0 ? PIT_WHEEL_REST_ALONG : -PIT_WHEEL_REST_ALONG)
286:   };
