const wait = (ms) => new Promise((r) => setTimeout(r, ms));

async function findTarget() {
  for (let i = 0; i < 40; i++) {
    try {
      const list = await (await fetch('http://127.0.0.1:9222/json/list')).json();
      const page = list.find((t) => t.type === 'page' && t.url.includes('localhost:3000'));
      if (page) return page.webSocketDebuggerUrl;
    } catch {}
    await wait(500);
  }
  throw new Error('no page');
}

const wsUrl = await findTarget();
const ws = new WebSocket(wsUrl);
await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

let id = 0;
const pending = new Map();
ws.onmessage = (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    msg.error ? reject(new Error(JSON.stringify(msg.error))) : resolve(msg.result);
  }
};
function send(method, params = {}) {
  const msgId = ++id;
  return new Promise((resolve, reject) => {
    pending.set(msgId, { resolve, reject });
    ws.send(JSON.stringify({ id: msgId, method, params }));
  });
}
async function evaluate(expression) {
  const res = await send('Runtime.evaluate', {
    expression,
    awaitPromise: true,
    returnByValue: true,
    userGesture: true
  });
  if (res.exceptionDetails) {
    throw new Error(res.exceptionDetails.exception?.description || res.exceptionDetails.text);
  }
  return res.result.value;
}

const errors = [];
await send('Runtime.enable');
await send('Runtime.evaluate', { expression: '1' });
ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text);
  if (msg.method === 'Runtime.consoleAPICalled' && msg.params.type === 'error') {
    errors.push(msg.params.args.map((a) => a.value || a.description || '').join(' '));
  }
});

await wait(4000);
console.log('state before:', await evaluate('window.__apex?.state'));

// Start a demo race instantly.
await evaluate('window.__apex.demoRace(0)');
await wait(2500);
console.log('state after demoRace:', await evaluate('window.__apex?.state'));
console.log('laps/ai:', await evaluate('JSON.stringify({laps: __apex.race.totalLaps, ai: __apex.race.ai.length})'));

// Freeze the player at its own pit box and put the stop in service.
console.log('player box crew idle:', await evaluate(`(() => {
  const r = __apex.race; const box = r.world.playerPitBox;
  return JSON.stringify({ box: { x: box.x, z: box.z }, crew: box.crew.map((c) => ({ w: c.wheel, x: +c.idle.x.toFixed(2), z: +c.idle.z.toFixed(2), tyre: c.tyre.visible })) });
})()`));

// Verify AI crew boxes all idle inside their garage floor bounds.
console.log('ai crew idle bounds:', await evaluate(`(() => {
  const r = __apex.race;
  return JSON.stringify(r.world.pitBoxes.map((b) => ({
    team: b.team,
    ok: b.crew.every((c) => Math.abs(c.idle.x) < 4.85 && c.idle.z > -4.05 && c.idle.z < 4.45),
    count: b.crew.length
  })));
})()`));

await evaluate(`(() => {
  const r = __apex.race;
  const pit = r.pit;
  const box = r.world.playerPitBox;
  r.state = 'racing';
  r.player.pos = { x: box.x, z: box.z };
  r.player.yaw = box.yaw;
  r.player.vLong = 0; r.player.vLat = 0;
  r.player.progressDist = r.pit.entryProgress + box.routeProgress;
  pit.phase = 'servicing';
  pit.serviceStage = 'remove';
  pit.serviceTimer = 0;
  pit.wheels = { fl: 'old', fr: 'old', rl: 'old', rr: 'old' };
  for (let i = 0; i < 150; i++) __apex.tick(1 / 60);
})()`);
console.log('player crew deployed:', await evaluate(`(() => {
  const box = __apex.race.world.playerPitBox;
  return JSON.stringify(box.crew.map((c) => ({ w: c.wheel, x: +c.x.toFixed(2), z: +c.z.toFixed(2), tx: +c.target.x.toFixed(2), tz: +c.target.z.toFixed(2), tyre: c.tyre.visible })));
})()`));

// Remove two old wheels and fit one fresh one, then tick.
await evaluate(`(() => {
  const r = __apex.race;
  r.pit.wheels = { fl: 'removed', fr: 'removed', rl: 'new', rr: 'old' };
  for (let i = 0; i < 90; i++) __apex.tick(1 / 60);
})()`);
console.log('player wheel visuals:', await evaluate(`(() => {
  const car = __apex.race.playerCar;
  return JSON.stringify(car.wheels.map((w, i) => ({
    i, blend: +w.pitBlend.toFixed(2),
    fresh: w.pitFresh ? { vis: w.pitFresh.group.visible, blend: +w.pitFresh.blend.toFixed(2) } : null
  })));
})()`));
console.log('player crew tyres after fit:', await evaluate(`(() => {
  const box = __apex.race.world.playerPitBox;
  return JSON.stringify(box.crew.map((c) => ({ w: c.wheel, tyre: c.tyre.visible })));
})()`));

// Finish the stop and confirm the wheels snap back cleanly.
await evaluate(`(() => {
  const r = __apex.race;
  r.pit.wheels = { fl: 'new', fr: 'new', rl: 'new', rr: 'new' };
  for (let i = 0; i < 60; i++) __apex.tick(1 / 60);
  r.pit.phase = 'driving-out';
  for (let i = 0; i < 5; i++) __apex.tick(1 / 60);
})()`);
console.log('player wheels after release:', await evaluate(`(() => {
  const car = __apex.race.playerCar;
  return JSON.stringify(car.wheels.map((w) => ({
    blend: +w.pitBlend.toFixed(2), freshVisible: w.pitFresh?.group.visible,
    x: +w.steer.position.x.toFixed(2), y: +w.steer.position.y.toFixed(2)
  })));
})()`));

// AI stop: force an AI car into its box, service it, and check crew + wheels.
console.log('ai stop:', await evaluate(`(() => {
  const r = __apex.race;
  const a = r.ai.find((c) => c.pitBox);
  const pit = a.pit;
  pit.phase = 'service';
  pit.serviceDuration = 3;
  pit.serviceTimer = 1.2;
  pit.routeProgress = a.pitBox.routeProgress;
  pit.speed = 0; pit.x = a.pitBox.x; pit.z = a.pitBox.z; pit.yaw = a.pitBox.yaw;
  for (let i = 0; i < 90; i++) __apex.tick(1 / 60);
  return JSON.stringify({
    team: a.pitBox.team,
    crewDeployed: a.pitBox.crew.every((c) => Math.hypot(c.x - c.target.x, c.z - c.target.z) < 0.3),
    wheels: a.model.wheels.map((w) => ({ blend: +w.pitBlend.toFixed(2), fresh: w.pitFresh?.group.visible })),
    tyres: a.pitBox.crew.map((c) => c.tyre.visible)
  });
})()`));

console.log('runtime errors:', JSON.stringify(errors));
ws.close();
process.exit(0);

