playwright-cli -s=finish eval "() => {
  const r = __apex.race;
  r.state = 'racing';
  const cars = [{ name: 'YOU', root: r.playerCar.root, prog: () => r.player.progressDist }]
    .concat(r.ai.map((a, i) => ({ name: a.name || ('AI' + i), root: a.model.root, prog: () => a.dist })));
  const start = cars.map((c) => ({ name: c.name, x: c.root.position.x, z: c.root.position.z, prog: c.prog() }));
  let worst = { name: '', step: 0 };
  const prev = start.map((s) => ({ x: s.x, z: s.z, prog: s.prog }));
  let maxDrift = 0;
  for (let f = 0; f < 240; f++) {
    __apex.tick(1 / 60);
    cars.forEach((c, i) => {
      const dx = c.root.position.x - prev[i].x;
      const dz = c.root.position.z - prev[i].z;
      const step = Math.hypot(dx, dz);
      const dprog = Math.abs(c.prog() - prev[i].prog);
      if (step > worst.step) worst = { name: c.name, step: +step.toFixed(2), dprog: +dprog.toFixed(2) };
      maxDrift = Math.max(maxDrift, step);
      prev[i] = { x: c.root.position.x, z: c.root.position.z, prog: c.prog() };
    });
  }
  const moved = cars.map((c, i) => {
    const d = Math.hypot(c.root.position.x - start[i].x, c.root.position.z - start[i].z);
    return { name: c.name, movedFromGrid: +d.toFixed(1), progressDelta: +(c.prog() - start[i].prog).toFixed(1) };
  });
  return { start: start.map((s) => ({ name: s.name, x: +s.x.toFixed(1), z: +s.z.toFixed(1) })), worst, maxDrift: +maxDrift.toFixed(2), moved };
