333: function ribbonGeometry(track, offA, offB, y, { tile = 8, uA = 0, uB = 1 } = {}) {
334:   const N = track.N;
335:   const pos = [];
336:   const uv = [];
337:   const idx = [];
338:   const total = track.length;
339:   for (let i = 0; i <= N; i++) {
340:     const s = track.samples[i % N];
341:     const a = offA;
342:     const b = offB;
343:     pos.push(s.x + s.nx * a, y, s.z + s.nz * a);
344:     pos.push(s.x + s.nx * b, y, s.z + s.nz * b);
345:     const v = (i === N ? total : s.s) / tile;
346:     uv.push(uA, v, uB, v);
347:   }
348:   for (let i = 0; i < N; i++) {
349:     const a = i * 2;
350:     idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
351:   }
352:   const geo = new THREE.BufferGeometry();
353:   geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
354:   geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
355:   geo.setIndex(idx);
356:   geo.computeVertexNormals();
357:   return geo;
358: }
