360: function segmentRibbonGeometry(track, offsetA, offsetB, y, activeFn, colorFn, tileLen = 2.5) {
361:   const N = track.N;
362:   const pos = [];
363:   const col = [];
364:   const idx = [];
365:   let v = 0;
366:   for (let i = 0; i < N; i++) {
367:     if (!activeFn(i)) continue;
368:     const s = track.samples[i];
369:     const n = track.samples[(i + 1) % N];
370:     const oA = typeof offsetA === 'function' ? offsetA(i) : offsetA;
371:     const oB = typeof offsetB === 'function' ? offsetB(i) : offsetB;
372:     const lo = Math.min(oA, oB);
373:     const hi = Math.max(oA, oB);
374:     const ax = s.x + s.nx * lo, az = s.z + s.nz * lo;
375:     const bx = s.x + s.nx * hi, bz = s.z + s.nz * hi;
376:     const cx = n.x + n.nx * lo, cz = n.z + n.nz * lo;
377:     const dx = n.x + n.nx * hi, dz = n.z + n.nz * hi;
378:     const base = pos.length / 3;
379:     pos.push(ax, y, az, bx, y, bz, cx, y, cz, dx, y, dz);
380:     const c = colorFn(i, Math.floor(s.s / tileLen));
381:     for (let k = 0; k < 4; k++) col.push(c.r, c.g, c.b);
382:     idx.push(base, base + 2, base + 1, base + 1, base + 2, base + 3);
383:     v++;
384:   }
385:   const geo = new THREE.BufferGeometry();
386:   geo.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
387:   geo.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
388:   geo.setIndex(idx);
389:   geo.computeVertexNormals();
390:   return geo;
391: }
