function crowdTexture() {
  // One dense row of seated fans. The grandstand builder tiles this strip on
  // every terrace so the stand reads as a packed crowd from the track.
  return createCanvasTexture([512, 128], (ctx, w, h) => {
    ctx.fillStyle = '#15181d';
    ctx.fillRect(0, 0, w, h);
    const shirts = [
      '#e0d8c6', '#c23a30', '#3d78a8', '#e0a83c', '#2f7d55', '#d6d6d6',
      '#803c67', '#3a3a44', '#e2672b', '#5c7fa6', '#f0d34a', '#8b2f24'
    ];
    const skins = ['#e8b48f', '#c58c63', '#8d5a3b', '#f0c9a6', '#6b432d'];
    for (let x = -8; x < w + 10; x += 8 + Math.random() * 5) {
      const y = h * 0.55 + (Math.random() - 0.5) * 9;
      const shirt = shirts[(Math.random() * shirts.length) | 0];
      const skin = skins[(Math.random() * skins.length) | 0];
      // torso / shoulders
      ctx.fillStyle = shirt;
      ctx.fillRect(x - 4.5, y + 1, 10, 17);
      // head
      ctx.fillStyle = skin;
      ctx.beginPath();
      ctx.arc(x, y - 4, 2.7, 0, TAU);
      ctx.fill();
      // occasional raised arm
      if (Math.random() < 0.14) {
        ctx.strokeStyle = skin;
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.moveTo(x - 3, y + 5);
        ctx.lineTo(x - 6, y - 6);
        ctx.stroke();
      }
      // occasional scarf or little flag
      if (Math.random() < 0.09) {
        ctx.fillStyle = shirts[(Math.random() * shirts.length) | 0];
        ctx.fillRect(x + 4, y - 15, 2, 13);
      }
    }
    const shade = ctx.createLinearGradient(0, h * 0.7, 0, h);
    shade.addColorStop(0, 'rgba(8,10,12,0)');
    shade.addColorStop(1, 'rgba(8,10,12,.82)');
    ctx.fillStyle = shade;
    ctx.fillRect(0, h * 0.7, w, h * 0.3);
    ctx.fillStyle = 'rgba(255,255,255,.05)';
    for (let y = 12; y < h; y += 26) ctx.fillRect(0, y, w, 1);
  }, { repeat: [2, 1] });
}

function catchFenceTexture() {
  return createCanvasTexture([128, 128], (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(188,198,204,.85)';
    ctx.lineWidth = 1.4;
    for (let x = 0; x <= w; x += 16) {
      ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
    }
    for (let y = 0; y <= h; y += 16) {
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
    }
    ctx.strokeStyle = 'rgba(120,132,140,.9)';
    ctx.lineWidth = 2.6;
    ctx.strokeRect(0, 0, w, h);
  }, { repeat: [4, 2] });
}

