  const params = new URLSearchParams(window.location.search);
  const demo = params.get('demo');
  if (demo === 'garage') {
    setTimeout(enterGarage, 300);
  } else if (demo === 'draw') {
    setTimeout(() => {
      startDrawing();
      setTimeout(() => drawScreen.loadExample(0), 450);
    }, 300);
