      if (params.get('input') === '1') {
        input.gas = true;
        setTimeout(() => { input.right = true; }, 1200);
      }
    }, 350);
  }

  window.__apex = {
    get state() { return appState; },
    get race() { return race; },
    get drawScreen() { return drawScreen; },
    get showroom() { return showroom; },
    startDrawing,
    beginBuild,
    enterMenu,
    enterGarage,
    goToDraw,
    startRaceNow,
    pauseRace,
